/**
 * Responsibility: define domain action/request data and the existing action-provider port.
 * Input: machine identities, player-visible facts and neutral message references;
 * output: typed tools, arguments, request contexts and validation results.
 * Declarations grant no runtime authority or resources; engine-owned leases and
 * current-state checks remain separate. ActionProvider is an execution interface,
 * not serialized data. Existing optional extras and strict turn fields are preserved.
 */
import type { ToolCall } from "@ai-werewolf-arena/game-contract";
export { TOOL_NAMES, ACTION_STAGES, DEATH_SHOT_STAGES } from "@ai-werewolf-arena/game-contract";
export type {
  ToolArgMap,
  ToolName,
  ToolCall,
  TypedToolCall,
  ToolValidationResult,
  TurnConstraints,
  ActionStage,
} from "@ai-werewolf-arena/game-contract";

import type { EntityId } from "./identity";

export interface KnightDuelSelection {
  actorId: EntityId;
  targetId: EntityId;
}
export type KnightDuelCommit = "rejected" | "continue" | "night" | "terminal";
export type SelfDestructSelection =
  | { kind: "ordinary"; actorId: EntityId; targetId: null }
  | { kind: "white_wolf_king"; actorId: EntityId; targetId: EntityId | null };

import type { ActionRequest } from "@ai-werewolf-arena/game-contract/requests";
export type {
  ActionRequest,
  ActionRequestContext,
  ActionRequestExtras,
} from "@ai-werewolf-arena/game-contract/requests";

export interface ActionProvider {
  getAction(request: ActionRequest): Promise<ToolCall | null>;
}

/**
 * 负责从原 World 与明确阶段构造引擎行动请求。输入为演员、窗口、允许工具和中立摘要；
 * 输出固定日次、阶段、约束及玩家可见事实，完整构造之后交规则集按原顺序接线机制绑定。
 * 具体机制仍唯一持有权限、期限别名与资源提交；请求数据副本不是行动许可。
 * 本工厂不渲染本地化文案、不序列化运行范围，也不据阶段字符串新增角色权限。
 */
import { bindRulesetActionRequest } from "../../rulesets/action-request-bindings";
import type { MessageRef } from "@ai-werewolf-arena/game-contract";
import type { ActionRequest, ActionRequestExtras } from "@ai-werewolf-arena/game-contract/requests";
import type { GameEvent } from "@ai-werewolf-arena/game-contract/events";
import type {
  ActionStage,
  ActionWindow,
  EntityId,
  Phase,
  ToolName,
} from "@ai-werewolf-arena/game-contract";
import { World } from "../../core/domain/world";
import { buildAgentVisibleEventFeed } from "./agent_visible_event_feed";
import { buildTurnConstraintContext } from "./turn_constraints_context";

/**
 * 统一创建游戏对 Agent 的行动请求。
 *
 * 该工厂统一填入原生请求的日次、细粒度 stage、玩家可见事件与结构化行动约束；
 * 调用方提供机制附加数据，运行时权限仍由具体机制保存，不混入这些公共字段。
 */
export class GameActionRequestFactory {
  constructor(
    private readonly world: World,
    private readonly events: readonly GameEvent[],
    private readonly day: number,
  ) {}

  create(input: {
    phase: Phase;
    actorId: EntityId;
    allowedTools: ToolName[];
    stage: ActionStage;
    requiresAction: boolean;
    summary: string | MessageRef;
    actionWindow?: ActionWindow;
    context?: ActionRequestExtras;
  }): ActionRequest {
    // 公共事实由工厂生成；调用方只能提供机制特有的信息。
    const request: ActionRequest = {
      phase: input.phase,
      actorId: input.actorId,
      allowedTools: [...input.allowedTools],
      ...(input.actionWindow ? { actionWindow: input.actionWindow } : {}),
      context: {
        ...structuredClone(input.context ?? {}),
        day: this.day,
        stage: input.stage,
        turn_constraints: buildTurnConstraintContext({
          requiresAction: input.requiresAction,
          allowedTools: input.allowedTools,
          summary: input.summary,
        }),
        visible_events: buildAgentVisibleEventFeed(this.world, [...this.events], input.actorId),
      },
    };
    // 原输入的阶段仍逐分支读取，不用已构造的 context.stage 替代后续 getter；World 也只在命中时读。
    bindRulesetActionRequest(request, {
      stage: () => input.stage,
      world: () => this.world,
    });
    return request;
  }
}

/**
 * 开启已配置的匿名墙机会并收集原作者行动。输入为只读政策、World、Provider 及具名 RNG 工厂；输出为墙事实与窗口完成，库存和请求关闭归 authority，不改规则或取得其他能力。
 */
import type { ReadonlyBoardConfig } from "@ai-werewolf-arena/game-contract";
import {
  COMPONENT,
  Phase,
  type World,
  type ActionProvider,
  type GameEvent,
  type ToolCall,
} from "../../../../core/domain";
import { shuffled, type RandomSource } from "../../../../core/domain/random";
import { readWallTool } from "@ai-werewolf-arena/game-contract/facts/wall-notes";
import type { GameActionRequestFactory } from "../../../engine/action_request_factory";
import { ToolGateway } from "../../../gateway/tool_gateway";
import {
  openWall,
  closeWall,
  grantWallNote,
  sameWallAuthor,
  hasActiveWall,
  hasWallCommit,
  type WallAuthor,
} from "./authority";
export class WallNotesWindow {
  constructor(
    private readonly world: World,
    private readonly gateway: ToolGateway,
    private readonly events: GameEvent[],
  ) {}
  async execute(
    config: ReadonlyBoardConfig,
    requests: GameActionRequestFactory,
    provider: ActionProvider,
    day: number,
    isCurrent: () => boolean,
    random: () => RandomSource,
  ): Promise<void> {
    if (hasActiveWall(this.world)) throw new Error("wall_window_reentry");
    if (
      config.events?.pack !== "awa_wall_notes_once_v1" ||
      day !== 1 ||
      hasWallCommit(this.world) ||
      !isCurrent()
    )
      return;
    const pack = config.events;
    const windowCurrent = () =>
      isCurrent() && config.events === pack && pack.pack === "awa_wall_notes_once_v1";
    const a = openWall(this.world, windowCurrent);
    const cancel = () => {
      if (isCurrent())
        this.events.push({
          timestamp: Date.now(),
          type: "wall_notes_canceled",
          payload: { day: 1, eventId: "awa_wall_notes_v1", reason: "scope_changed" },
        });
    };
    const change = (
      author: WallAuthor,
      operation: "granted" | "accepted" | "rejected" | "revoked" | "expired",
      text?: string,
    ) =>
      this.events.push({
        timestamp: Date.now(),
        type: "wall_note_changed",
        payload: {
          actorId: author.id,
          day: 1,
          eventId: "awa_wall_notes_v1",
          itemId: "anonymous_note",
          instanceId: author.instanceId,
          operation,
          remaining: author.remaining,
          expired: operation === "expired",
          ...(operation === "accepted" ? { text: text! } : {}),
        },
      });
    const base = { day: 1 as const, eventId: "awa_wall_notes_v1" as const };
    try {
      this.events.push({ timestamp: Date.now(), type: "wall_notes_started", payload: base });
      const authors = this.world
        .getAliveEntityIds()
        .sort((x, y) => x - y)
        .flatMap((id) => {
          const author = grantWallNote(this.world, a, id);
          if (!author) return [];
          change(author, "granted");
          return [author];
        });
      const calls = authors.map((author) => ({
        author,
        request: requests.create({
          actorId: author.id,
          phase: Phase.Voting,
          allowedTools: ["write_note"],
          stage: "wall_notes",
          requiresAction: false,
          summary: { key: "request.summary.wall_notes" },
          context: { wall_id: a.token, item_instance_id: author.instanceId, allow_fallback: false },
        }),
      }));
      const results = await Promise.allSettled(
        calls.map(({ author, request }) =>
          sameWallAuthor(this.world, a, author)
            ? Promise.resolve().then(() =>
                sameWallAuthor(this.world, a, author) ? provider.getAction(request) : null,
              )
            : Promise.resolve(null),
        ),
      );
      const failure = results.find((result) => result.status === "rejected");
      if (failure?.status === "rejected") throw failure.reason;
      if (!windowCurrent()) {
        cancel();
        return;
      }
      const accepted: Array<{ author: WallAuthor; text: string }> = [];
      for (let i = 0; i < calls.length; i++) {
        const { author } = calls[i],
          result = results[i];
        if (!sameWallAuthor(this.world, a, author)) {
          change(author, "revoked");
          continue;
        }
        const call = result.status === "fulfilled" ? readWallTool(result.value) : null;
        if (!call) {
          if (result.status === "fulfilled" && result.value !== null) change(author, "rejected");
          continue;
        }
        const valid = this.gateway.validateAndSanitize(this.world, author.id, call, {
          phase: Phase.Voting,
          day: 1,
          wallScope: a,
          wallId: a.token,
          itemInstanceId: author.instanceId,
        });
        if (!sameWallAuthor(this.world, a, author)) {
          change(author, "revoked");
          continue;
        }
        if (!valid.ok) {
          change(author, "rejected");
          continue;
        }
        author.remaining = 0;
        author.note.remaining = 0;
        change(author, "accepted", call.args.text);
        accepted.push({ author, text: call.args.text });
      }
      if (!windowCurrent()) {
        cancel();
        return;
      }
      const current = accepted.filter((row) => {
        if (sameWallAuthor(this.world, a, row.author)) return true;
        change(row.author, "revoked");
        return false;
      });
      const ordered = current.sort((x, y) =>
        x.text < y.text ? -1 : x.text > y.text ? 1 : x.author.id - y.author.id,
      );
      const final = shuffled(ordered, random());
      if (!windowCurrent() || final.some((row) => !sameWallAuthor(this.world, a, row.author))) {
        cancel();
        return;
      }
      this.events.push(
        {
          timestamp: Date.now(),
          type: "wall_note_order_recorded",
          payload: {
            ...base,
            rows: final.map(({ author, text }, rank) => ({
              actorId: author.id,
              instanceId: author.instanceId,
              text,
              rank,
            })),
          },
        },
        {
          timestamp: Date.now(),
          type: "wall_notes_published",
          payload: { ...base, texts: final.map((row) => row.text) },
        },
      );
    } finally {
      closeWall(this.world, a);
      for (const author of a.authors.values()) change(author, "expired");
    }
  }
}

/**
 * Opens the Debater speaking opportunity and dispatches the selected debate through its
 * authority. Inputs are the current day participants, provider and gateway; outputs preserve the
 * debate event and window result. It never bypasses participant identity checks after the
 * provider await.
 */
import type { ReadonlyBoardConfig, DebaterState } from "@ai-werewolf-arena/game-contract";
import {
  COMPONENT,
  Role,
  Camp,
  Phase,
  type World,
  type ActionProvider,
  type GameEvent,
  type BadgeComponent,
  type VotingRightComponent,
} from "../../../../core/domain";
import { ToolGateway } from "../../../gateway/tool_gateway";
import type { GameActionRequestFactory } from "../../../engine/action_request_factory";
import { commitSheriffBadgeChoice, badgeSuccessorEligible } from "../../sheriff/badge";
import { getDebaterState } from "./state";
import {
  captureDebateParticipant,
  sameDebateParticipant,
  openDebate,
  closeDebate,
  hasDebateCommit,
  commitDebate,
  blockDebateVote,
  nextDebateId,
  hasActiveDebate,
  type DebateAuthority,
} from "./authority";
/** Finite AWA adaptation: before one scheduled speech, two public statements, then a sealed anonymous ballot. */
export class DebaterWindow {
  constructor(
    private readonly world: World,
    private readonly gateway: ToolGateway,
    private readonly events: GameEvent[],
  ) {}
  async execute(
    config: ReadonlyBoardConfig,
    requests: GameActionRequestFactory,
    provider: ActionProvider,
    targetId: number,
    day: number,
    isCurrent: () => boolean,
  ): Promise<{ skipSpeech: boolean }> {
    if (hasActiveDebate(this.world)) throw new Error("debate_window_reentry");
    const empty = { skipSpeech: false };
    if (!isCurrent()) return empty;
    const actorId = this.world.getEntityIdsByRole(Role.Debater).find((id) => {
      const role = this.world.getComponent(id, COMPONENT.Role),
        state = getDebaterState(role);
      return (
        id !== targetId &&
        role?.camp === Camp.Good &&
        this.world.getAliveEntityIds().includes(id) &&
        state?.remaining === 1 &&
        state.choice === null &&
        !hasDebateCommit(this.world, id)
      );
    });
    if (actorId === undefined) return empty;
    let participants = new Map(
        this.world.getAliveEntityIds().flatMap((id) => {
          const p = captureDebateParticipant(this.world, id);
          return p ? [[id, p] as const] : [];
        }),
      ),
      actor = participants.get(actorId),
      target = participants.get(targetId);
    if (!actor || !target) return empty;
    const state = getDebaterState(actor.role)!,
      policy = state.policy;
    if (policy !== "awa_melbourne_2026_speech_gap_v1") return empty;
    const badgeSnapshot = (id: number) => {
      const badge = this.world.getComponent(id, COMPONENT.Badge),
        vote = this.world.getComponent(id, COMPONENT.VotingRight);
      return {
        id,
        badge,
        vote,
        isSheriff: badge?.isSheriff,
        destroyed: badge?.destroyed,
        weight: badge?.voteWeight,
        handoff: badge?.handoffPolicy,
        canVote: vote?.canVote,
        voteWeight: vote?.weight,
      };
    };
    const badges = [badgeSnapshot(actorId), badgeSnapshot(targetId)];
    const sameBadges = () =>
      badges.every(
        (b) =>
          this.world.getComponent(b.id, COMPONENT.Badge) === b.badge &&
          this.world.getComponent(b.id, COMPONENT.VotingRight) === b.vote &&
          b.badge?.isSheriff === b.isSheriff &&
          b.badge?.destroyed === b.destroyed &&
          b.badge?.voteWeight === b.weight &&
          b.badge?.handoffPolicy === b.handoff &&
          b.vote?.canVote === b.canVote &&
          b.vote?.weight === b.voteWeight,
      );
    const authority: DebateAuthority = {
      id: nextDebateId(this.world, day, actorId, targetId),
      day,
      actorId,
      targetId,
      stage: "challenge",
      participants,
    };
    let accepted = false,
      choice: typeof state.choice = null;
    const current = () =>
      isCurrent() &&
      sameDebateParticipant(this.world, actor) &&
      sameDebateParticipant(this.world, target) &&
      getDebaterState(actor.role) === state &&
      state.policy === policy &&
      state.remaining === (accepted ? 0 : 1) &&
      state.choice === choice &&
      (choice === null || (choice.day === day && choice.targetId === targetId)) &&
      hasDebateCommit(this.world, actorId) === accepted &&
      sameBadges();
    const extras = {
      debate_id: authority.id,
      debate_actor_id: actorId,
      debate_target_id: targetId,
      allow_fallback: false,
    };
    const canceled = () => {
      if (isCurrent())
        this.events.push({
          timestamp: Date.now(),
          type: "debate_canceled",
          payload: { actorId, targetId, day, reason: "scope_changed" },
        });
      return empty;
    };
    openDebate(this.world, authority);
    try {
      const request = requests.create({
        actorId,
        phase: Phase.Day,
        allowedTools: ["challenge"],
        stage: "debate_challenge",
        requiresAction: false,
        summary: { key: "request.summary.debate_challenge", parameters: { target: targetId } },
        context: extras,
      });
      if (!current()) return empty;
      const action = await provider.getAction(request);
      if (!current() || action?.name !== "challenge") return empty;
      const checked = this.gateway.validateAndSanitize(this.world, actorId, action, {
        phase: Phase.Day,
        day,
        debateId: authority.id,
      });
      if (!checked.ok || !current()) return empty;
      participants = new Map(
        this.world.getAliveEntityIds().flatMap((id) => {
          const p = captureDebateParticipant(this.world, id);
          return p ? [[id, p] as const] : [];
        }),
      );
      authority.participants = participants;
      commitDebate(this.world, actorId);
      (state as Pick<DebaterState, "remaining">).remaining = 0;
      choice = { day, targetId };
      (state as Pick<DebaterState, "choice">).choice = choice;
      accepted = true;
      this.events.push(
        { timestamp: Date.now(), type: "debater_revealed", payload: { actorId, day } },
        { timestamp: Date.now(), type: "debate_started", payload: { actorId, targetId, day } },
      );
      authority.stage = "speech";
      for (const speaker of [actorId, targetId]) {
        if (!current()) return canceled();
        const speechRequest = requests.create({
          actorId: speaker,
          phase: Phase.Day,
          allowedTools: ["speak"],
          stage: "debate_speech",
          requiresAction: true,
          summary: { key: "request.summary.debate_speech" },
          context: extras,
        });
        if (!current()) return canceled();
        const speech = await provider.getAction(speechRequest);
        if (!current()) return canceled();
        if (speech?.name !== "speak") continue;
        const valid = this.gateway.validateAndSanitize(this.world, speaker, speech, {
          phase: Phase.Day,
          day,
        });
        if (!current()) return canceled();
        if (valid.ok && valid.sanitizedCall?.name === "speak")
          this.events.push({
            timestamp: Date.now(),
            type: "debate_speech",
            payload: { actorId: speaker, text: valid.sanitizedCall.args.text },
          });
      }
      authority.stage = "ballot";
      // Construct the entire round before invoking a provider. No partial totals/individual events escape.
      const ballotRequests = [...participants.keys()].map((voterId) => ({
        voterId,
        request: requests.create({
          actorId: voterId,
          phase: Phase.Day,
          allowedTools: ["debate_vote"],
          stage: "debate_ballot",
          requiresAction: true,
          summary: { key: "request.summary.debate_ballot" },
          context: extras,
        }),
      }));
      if (!current()) return canceled();
      const replies = await Promise.all(
        ballotRequests.map(async ({ voterId, request }) => ({
          voterId,
          call:
            current() && sameDebateParticipant(this.world, participants.get(voterId)!)
              ? await provider.getAction(request)
              : null,
        })),
      );
      if (!current()) return canceled();
      const ballots = replies.map(({ voterId, call }) => {
        const p = participants.get(voterId)!;
        if (!sameDebateParticipant(this.world, p) || call?.name !== "debate_vote")
          return { voterId, support: null };
        const checked = this.gateway.validateAndSanitize(this.world, voterId, call, {
          phase: Phase.Day,
          day,
          debateId: authority.id,
        });
        return {
          voterId,
          support:
            checked.ok &&
            checked.sanitizedCall?.name === "debate_vote" &&
            sameDebateParticipant(this.world, p)
              ? checked.sanitizedCall.args.support
              : null,
        };
      });
      if (!current()) return canceled();
      // Revalidate all already collected ballots once more, since another actor's validator can revoke them.
      for (const ballot of ballots)
        if (!sameDebateParticipant(this.world, participants.get(ballot.voterId)!))
          ballot.support = null;
      const eligibleCount = participants.size,
        supports = ballots.filter((b) => b.support === true).length,
        rejects = ballots.filter((b) => b.support === false).length,
        abstentions = eligibleCount - supports - rejects,
        success = supports > eligibleCount / 2,
        blockedId = success ? targetId : actorId;
      const targetBadge = this.world.getComponent(targetId, COMPONENT.Badge),
        needsBadge = success && targetBadge?.isSheriff === true && !targetBadge.destroyed;
      if (needsBadge && !badgeSuccessorEligible(this.world, targetId, actorId)) return canceled();
      if (!current()) return canceled();
      // Commit result, life-scoped penalty and any badge handoff synchronously after the final gate.
      if (needsBadge)
        commitSheriffBadgeChoice(this.world, targetId, "debate", this.events, actorId);
      blockDebateVote(this.world, blockedId, actorId, day);
      this.events.push(
        {
          timestamp: Date.now(),
          type: "debate_ballots_recorded",
          payload: { actorId, targetId, day, eligibleCount, ballots },
        },
        {
          timestamp: Date.now(),
          type: "debate_resolved",
          payload: {
            actorId,
            targetId,
            day,
            eligibleCount,
            supports,
            rejects,
            abstentions,
            success,
            blockedId,
          },
        },
      );
      return { skipSpeech: success };
    } finally {
      closeDebate(this.world, authority);
    }
  }
}

/**
 * 负责秘密之身放逐免死、公开翻牌与必需活人发言的完整同步交接。
 * 输入为原运行对象的晚读查询和已映射目标；输出原行动请求以及是否已处理放逐，不输出 JSON 租约。
 * 身体付款先于公开事实和必需录制；失败保留已付／已发布前缀，不重试或回滚。原权威独占资源和许可。
 * 生成器仅在原 Provider 等待点交出请求；调用方负责原唯一 await，拒绝时必须 return 进入已打开的 finally。
 * 非本族或不触发路径同步结束，不增加等待；发言复验、提交和关闭仍按原顺序执行。
 */
import { Phase } from "../../../../core/domain/identity";
import type { ActionRequest, ToolCall } from "@ai-werewolf-arena/game-contract";
import type { ReadonlyBoardConfig } from "@ai-werewolf-arena/game-contract";
import type { GameEvent } from "@ai-werewolf-arena/game-contract/events";
import type { World } from "../../../../core/domain/world";
import type { GameActionRequestFactory } from "../../../engine/action_request_factory";
import type { ToolGateway } from "../../../gateway/tool_gateway";
import { checkpointNobleBodyAuthority, consumeSecretBodyExile } from "./authority";
import {
  openNobleBodyRevealRequest,
  nobleBodyRequestScope,
  commitNobleBodyRevealSpeech,
  closeNobleBodyRequest,
} from "./requests";
import { getSessionRecorder } from "../../../../recording/recording_context";
import { safeRecordLogicOp } from "../../../../recording/session_recorder";

/** 原对象的只读视图；getter 在原表达式位置读取，不缓存 World、日次、回调或工厂方法，也不授予许可。 */
export interface SecretBodyExileRevealQueries {
  readonly enabled: ReadonlyBoardConfig["nobleSecretBody"];
  readonly world: World;
  readonly events: GameEvent[];
  readonly requests: Pick<GameActionRequestFactory, "create">;
  readonly toolGateway: Pick<ToolGateway, "validateAndSanitize">;
  readonly day: number;
  readonly isCurrent: (() => boolean) | undefined;
}

/** false 表示继续普通放逐；true 表示已完成翻牌。暂停时仅交原请求，不能据请求副本代替当前 scope。 */
export function* revealSecretBodyExile(
  queries: SecretBodyExileRevealQueries,
  effectiveTarget: number,
): Generator<ActionRequest, boolean, ToolCall | null> {
  if (queries.enabled) {
    const owned = checkpointNobleBodyAuthority(queries.world, true);
    if (effectiveTarget === owned.bodyId && owned.body.body.kind === "intact") {
      // 先耗身，再发布与必需录制；这些失败仍处于打开发言 scope 之前。
      const receipt = consumeSecretBodyExile(queries.world, queries.day),
        payload = { policy: "awa_noble_secret_body_v1" as const, ...receipt };
      queries.events.push({ timestamp: Date.now(), type: "secret_body_revealed", payload });
      getSessionRecorder()?.recordRequiredLogicOp({
        scope: "resolution",
        op: "secret_body_revealed",
        actorId: receipt.actorId,
        phase: Phase.Voting,
        status: "ok",
        output: payload,
      });
      const request = queries.requests.create({
          actorId: receipt.actorId,
          phase: Phase.Voting,
          allowedTools: ["speak"],
          stage: "awakened_idiot_reveal_speech",
          requiresAction: true,
          summary: { key: "request.summary.secret_body_reveal" },
          context: { allow_fallback: false, action_failure_policy: "error" },
        }),
        scope = openNobleBodyRevealRequest(
          queries.world,
          queries.day,
          request,
          queries.isCurrent ?? (() => true),
        );
      try {
        // 这里只暂停，不调用 Provider；恢复后先复验原 scope，再校验和提交。
        const action = yield request;
        if (nobleBodyRequestScope(queries.world, request) !== scope || action?.name !== "speak")
          throw Error("secret_body_reveal_speech_required");
        const valid = queries.toolGateway.validateAndSanitize(queries.world, receipt.actorId, action, {
          phase: Phase.Voting,
          day: queries.day,
          deferOperation: true,
        });
        if (
          !valid.ok ||
          !valid.sanitizedCall ||
          nobleBodyRequestScope(queries.world, request) !== scope
        )
          throw Error("secret_body_reveal_speech_required");
        const spoken = commitNobleBodyRevealSpeech(queries.world, scope, valid.sanitizedCall);
        queries.events.push({
          timestamp: Date.now(),
          type: "secret_body_reveal_speech",
          payload: { policy: "awa_noble_secret_body_v1", ...spoken },
        });
        safeRecordLogicOp({
          scope: "gateway",
          op: "validate_tool_call",
          actorId: receipt.actorId,
          phase: Phase.Voting,
          status: "ok",
          input: { tool: "speak", args: { text: spoken.text } },
        });
      } finally {
        // 成功／复验错误均关闭一次；Provider 拒绝由调用方 return 驱动这里，关闭错误沿原 finally 优先。
        closeNobleBodyRequest(scope);
      }
      return true;
    }
  }
  return false;
}

import type { ActionProvider, GameEvent } from "../../../../core/domain/model";
import { Phase } from "../../../../core/domain/identity";
import type { World } from "../../../../core/domain/world";
import type { ToolGateway } from "../../../gateway/tool_gateway";
import type { GameActionRequestFactory } from "../../../engine/action_request_factory";
import {
  openOrderPrinceChoice,
  assertOrderPrinceCurrent,
  commitOrderPrinceChoice,
  closeOrderPrinceChoice,
} from "./authority";

/** Only called after the original first ballot, before any exile or PK effects. */
export async function runOrderPrinceChoice(
  world: World,
  requests: GameActionRequestFactory,
  provider: ActionProvider,
  gateway: ToolGateway,
  events: GameEvent[],
  day: number,
  isCurrent: () => boolean,
): Promise<boolean> {
  const actorId = openOrderPrinceChoice(world, day);
  if (actorId === null) return false;
  const current = () => {
    assertOrderPrinceCurrent(world, actorId);
    if (!isCurrent()) throw new Error("order_prince_choice_stale");
  };
  try {
    current();
    const choice = await provider.getAction(
      requests.create({
        phase: Phase.Voting,
        actorId,
        allowedTools: ["reset_exile_vote"],
        stage: "order_prince_choice",
        requiresAction: true,
        summary: { key: "request.summary.order_prince_choice" },
        context: { action_failure_policy: "error", allow_fallback: false },
      }),
    );
    current();
    if (choice?.name !== "reset_exile_vote") throw new Error("order_prince_choice_missing");
    const checked = gateway.validateAndSanitize(world, actorId, choice, {
      phase: Phase.Voting,
      day,
    });
    current();
    if (!checked.ok || checked.sanitizedCall?.name !== "reset_exile_vote")
      throw new Error("order_prince_choice_invalid");
    const activate = checked.sanitizedCall.args.activate;
    commitOrderPrinceChoice(world, actorId, day, activate);
    events.push({
      timestamp: Date.now(),
      type: "order_prince_choice_committed",
      payload: { actorId, day, activate },
      audience: Object.freeze([actorId]),
    });
    if (!activate) return false;
    events.push({
      timestamp: Date.now(),
      type: "order_prince_revote_started",
      payload: { actorId },
    });
    current();
    const speech = await provider.getAction(
      requests.create({
        phase: Phase.Voting,
        actorId,
        allowedTools: ["speak"],
        stage: "order_prince_speech",
        requiresAction: true,
        summary: { key: "request.summary.order_prince_speech" },
        context: { action_failure_policy: "error", allow_fallback: false },
      }),
    );
    current();
    if (speech?.name !== "speak") throw new Error("order_prince_speech_missing");
    const validated = gateway.validateAndSanitize(world, actorId, speech, {
      phase: Phase.Voting,
      day,
    });
    current();
    if (!validated.ok || validated.sanitizedCall?.name !== "speak")
      throw new Error("order_prince_speech_invalid");
    events.push({
      timestamp: Date.now(),
      type: "day_speech",
      payload: { actorId, text: validated.sanitizedCall.args.text },
    });
    return true;
  } finally {
    closeOrderPrinceChoice(world);
  }
}
